import java.io.*;import java.util.*;public class Main{private static long gcd(long a,long b){while(b!=0){long t=a%b;a=b;b=t;}return a;}public static void main(String[]args) throws Exception{BufferedReader br=new BufferedReader(new InputStreamReader(System.in));StringBuilder sb=new StringBuilder();int T=Integer.parseInt(br.readLine().trim());for(int i=0;i<T;i++){String line;while((line=br.readLine())!=null&&line.trim().isEmpty()){}StringTokenizer st=new StringTokenizer(line);long N=Long.parseLong(st.nextToken());long M=Long.parseLong(st.nextToken());sb.append(gcd(N,M)).append('\n');}System.out.print(sb.toString());}}